-- Languages follow the business's plan, enforced on the server (Section 4). Safe to run twice.
-- Rollback: sql/rollback/zella_plan_languages_rollback.sql (generated by tests/setup/make_rollback.py planlang).
--
-- P2  No language check looked at the plan: Settings > Languages and the setup saved up to four languages for any
--     business, and calls used them all.
--     Now the number of languages a business may use (the main one included) is the plan's limits.languages:
--       - Settings > Languages refuses more (PLAN_LANGUAGES), whoever calls it (the CRM, the API);
--       - the setup's language choice is refused the same way (reported, not silently cut);
--       - at call time, a business over its allowance (for example after moving to a smaller plan) answers in its
--         main language and the first extra languages up to the allowance, and the rest are not offered.
--     No limit applies when the plan sets none, or the business has no current subscription; that matches
--     zella_entitlement_allows. Production has no plans defined (5 Nov), so nothing changes until plans are.
--     No plan, price or limit is created here.

-- the plan's language allowance (the main language counts as one), or null for no limit
create or replace function public.zella_language_allowance(p_business_id uuid) returns integer
language plpgsql stable security definer set search_path = public as $$
declare s public.subscriptions; v text;
begin
  if not public.zella_has_role(p_business_id, array['owner','admin','manager','staff','viewer']) then raise exception 'NOT_ALLOWED'; end if;
  s := public.zella_current_subscription(p_business_id);
  if s.id is null then return null; end if;
  select p.limits ->> 'languages' into v from public.plans p where p.id = s.plan_id;
  if v is null or v !~ '^[0-9]{1,2}$' then return null; end if;
  return greatest(v::int, 1);
end $$;
revoke execute on function public.zella_language_allowance(uuid) from public, anon;
grant execute on function public.zella_language_allowance(uuid) to authenticated, service_role;

do $$
declare def text;
begin
  def := pg_get_functiondef('public.zella_business_language_save(uuid, text, text[], text)'::regprocedure);
  if position('zella_plan_languages' in def) = 0 then
    def := replace(def, $a$  if cardinality(v_extras) > 3 then raise exception 'TOO_MANY_LANGUAGES'; end if;$a$,
                        $a$  if cardinality(v_extras) > 3 then raise exception 'TOO_MANY_LANGUAGES'; end if;
  if public.zella_language_allowance(p_business_id) is not null and 1 + cardinality(v_extras) > public.zella_language_allowance(p_business_id) then   /* zella_plan_languages */
    raise exception 'PLAN_LANGUAGES' using hint = 'The plan allows ' || public.zella_language_allowance(p_business_id) || ' language(s), the main one included.';
  end if;$a$);
    if position('zella_plan_languages' in def) = 0 then raise exception 'zella_business_language_save has changed; review this patch'; end if;
    execute def;
  end if;

  def := pg_get_functiondef('public.zella_setup_language_apply(uuid, text, text)'::regprocedure);
  if position('zella_plan_languages' in def) = 0 then
    def := replace(def, $a$  v_greeting := nullif(trim(regexp_replace(coalesce(p_greeting, ''), '\s+', ' ', 'g')), '');$a$,
                        $a$  if public.zella_language_allowance(p_business_id) is not null and 1 + cardinality(v_extras) > public.zella_language_allowance(p_business_id) then   /* zella_plan_languages */
    return jsonb_build_object('ok', false, 'reason', 'PLAN_LANGUAGES');
  end if;
  v_greeting := nullif(trim(regexp_replace(coalesce(p_greeting, ''), '\s+', ' ', 'g')), '');$a$);
    if position('zella_plan_languages' in def) = 0 then raise exception 'zella_setup_language_apply has changed; review this patch'; end if;
    execute def;
  end if;

  def := pg_get_functiondef('public.zella_business_language_plan(uuid)'::regprocedure);
  if position('zella_plan_languages' in def) = 0 then
    def := replace(def, $a$    from jsonb_array_elements(v_cat) e where e ->> 'code' = any (l.extra_languages) and e ->> 'code' <> l.primary_language;$a$,
                        $a$    from jsonb_array_elements(v_cat) e where e ->> 'code' = any (l.extra_languages) and e ->> 'code' <> l.primary_language;
  -- over the plan's allowance (a smaller plan): the first extra languages up to it, never more /* zella_plan_languages */
  if public.zella_language_allowance(p_business_id) is not null and jsonb_array_length(v_extra) > public.zella_language_allowance(p_business_id) - 1 then
    select coalesce(jsonb_agg(x order by i), '[]'::jsonb) into v_extra from jsonb_array_elements(v_extra) with ordinality t(x, i) where i <= public.zella_language_allowance(p_business_id) - 1;
  end if;$a$);
    if position('zella_plan_languages' in def) = 0 then raise exception 'zella_business_language_plan has changed; review this patch'; end if;
    execute def;
  end if;
end $$;
